add('14_002','巨手近景自右下斜向左上，卷曲手指围住董白小型头身，白色接触亮点在腕侧。',['巨大的手','董白局部','接触亮点'],['手指圈住董白'],['董白黑白头发露在指间上方','手背向镜头'],'斜向速度线与灰白底面',[],'Action，巨手沿已见方向合拢至源握姿；只短抓握，不补来手长路线或被抓前腾空。',['巨手已贴近董白，指间尚有窄开口',['手指圈紧身侧','指间开口收窄至源握姿'],'断刃之后转为受困，接触兑现','董白头发露在指间，手握住'],'最短合指前导由原抓握结果准入；不描写挤压损伤或隐藏身体。',2,['70mm略俯视巨手近景，手背从右下斜向左上，董白黑白头发露在上方指间，腕侧浅色亮点居下中；固定机位，手指包围关系清楚。','巨大的手指沿董白身侧圈拢，指间窄隙逐渐合小，黑白头发在上方短短一颤。手背随握紧绷出褶线，腕侧亮点一闪收弱，手维持抓住的姿态。','背景为灰蓝低亮远层，斜向柔光带很浅，手背轮廓清楚。','无台词。','左上柔光照出灰橄榄手背大面，指缝冷暗，腕侧亮点冷白而短。','一声短促掌指接触，衣料一下绷紧，余响很快收住。'],flags=['G'],bgrefs=['第20話_10_001.jpg'])
DATA[-1]['admissions']=[{'claim':'巨手手指圈住董白','visual_evidence':'源指间头发与合指抓握关系清晰，只安排最短合指接触前导'}]
add('14_003','欧迈及巨形正面上身在后，巨手横在下前，董白头颈从指间上方露出、头后仰。',['欧迈及巨形','董白','巨手','群像'],[],['董白身体被包在指间','头后仰嘴开','巨形脸全黑'],'后方黑灰群像和低处白雾',[['KEUUK!!!','董白','くっ……！']],'Reaction，抓握已经成立，董白后仰到源反应锚点，头颈和呼吸允许短局部变化；不再次抓紧。',['董白被握着，头露在指上',['头颈向后抬起','短吐气后下颌绷住'],'受困后的呼吸与反应同拍，巨形握持不变','头仍后仰，抓握持续'],'手指包围与前格相同，镜内不追加压迫或挣脱路径；短两秒让结果读清。',3,['50mm平视巨形与董白的关系中近景，巨形全黑脸在上后，巨大手指横列下前，董白头颈从指间上方露出；固定机位，抓握关系和后仰脸完整。','董白的头颈向后抬起，嘴唇骤然张开，短吐气之后下颌又绷紧，双马尾在指上轻轻颤动。欧迈及巨形的胸肩随一口低呼吸微动，巨手持续包着她，手指间距稳定；她的头仍停在后仰方向。','后方背景是层叠黑灰群像，冷白低雾托亮手指外缘，远处灰蓝层很淡。','董白发出：“くっ……！”（受阻的短促女声，咬着气息挤出，近距离。）','冷白柔光贴亮董白脸和指节上缘，巨形脸部保持厚黑，胸肩灰橄榄暗面宽重。','一口被截短的吐气，衣料持续绷着的细响，远处水声很轻。'],flags=['P','G'],bgmode='physical')
add('15_001','青梅男头盔和脸下部特写占右侧，三条横缝在中央右前，汗滴与黑点在盔边，左侧空。',['青梅男','三横缝头盔','汗滴'],[],['头朝左侧','口部微张','下颌发紧'],'灰色简化底面',[['她,她输了?!','青梅男','か、彼女が負けた？！'],['这不可能...!','青梅男','そんなはずは……！']],'Reaction，眼部不可见，以头颈后收、可见嘴部和汗表现源惊讶；不让铁盔眉动。',['青梅男头向左，嘴微张',['头颈短退、嘴开','下颌收紧，汗滴滑低'],'看见结果后从惊问到不信，同一机位自然停顿','盔朝左，口部仍发紧'],'两句短反应同机位，完整头颈参与；不新增跪倒或冲入动作。',5,['100mm平视青梅男头盔和下半脸特写，钢灰盔占右侧前景，三条横缝沿中央右侧排列，可见下颌在右下，左侧留空；固定机位。','青梅男的头颈短短向后收，嘴唇张开，第一句在气息里卡住。停半拍后下颌绷紧，口部再次开合，盔边汗滴慢慢滑低；钢盔仍朝左侧，呼吸在可见颈侧起伏。','背景为低亮灰蓝远层，左侧空区有柔弱冷灰明暗，不补额外器物。','青梅男说：“か、彼女が負けた？！そんなはずは……！”（年轻男声，第一句惊得卡顿，停顿后压低不信，语速自然。）','冷白柔光照亮钢灰盔的斜面和汗滴，横缝保留厚黑，下颌处浅灰影清楚。','一口突然吸气，颈侧衣料短擦，随后短短吐气。'],flags=['P','D'],bgrefs=['第20話_10_001.jpg'])
